import { useState, useEffect } from "react";

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Upload, FileText, Loader2, CheckCircle2, AlertCircle } from "lucide-react";
import { useTranslation } from "react-i18next";

import Modal from "@/components/ui/Modal";

import { uploadAttendance, fetchLatestImportJob, fetchImportJobStatus, getCurrentWorkspaceId } from "@/lib/api";
import { cn } from "@/lib/utils";

interface AttendanceImportDialogProps {
  isOpen: boolean;
  onClose: () => void;
  endpoint: string; // e.g., "/attendance/upload" or "/attendance/logs/upload"
  title: string;
  targetType: string; // "adjustment", "log", or "employee"
  customRequirements?: string[];
}

export default function AttendanceImportDialog({ 
  isOpen, 
  onClose, 
  endpoint, 
  title, 
  targetType,
  customRequirements
}: AttendanceImportDialogProps) {
  const { t } = useTranslation();
  const wsId = getCurrentWorkspaceId();
  const queryClient = useQueryClient();
  const [file, setFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);
  const [activeJobId, setActiveJobId] = useState<string | null>(null);

  const { data: jobStatus } = useQuery({
    queryKey: ["import-job", activeJobId],
    queryFn: () => fetchImportJobStatus(wsId!, activeJobId!),
    enabled: !!activeJobId && !!wsId,
    refetchInterval: (query) => {
        const status = query.state.data?.status;
        return (status === "processing" || status === "pending") ? 1000 : false;
    }
  });

  const { data: latestJob } = useQuery({
    queryKey: ["latest-import-job", wsId, targetType],
    queryFn: () => fetchLatestImportJob(wsId!, targetType),
    enabled: isOpen && !!wsId,
  });

  useEffect(() => { if (latestJob) setActiveJobId(latestJob.id); }, [latestJob]);

  const handleUpload = async () => {
    if (!file || !wsId) return;
    setUploading(true);
    try {
      const result = await uploadAttendance(wsId, file, endpoint);
      setActiveJobId(result.job_id); setFile(null);
      queryClient.invalidateQueries({ queryKey: ["latest-import-job"] });
    } catch (error) { console.error(error); } finally { setUploading(false); }
  };

  const isFinished = jobStatus?.status === "completed" || jobStatus?.status === "failed";

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={title} subtitle={t("attendance_import.subtitle")} icon={<Upload size={24} />} maxWidth="lg">
      {activeJobId ? (
        <div className="space-y-5 pt-2 animate-in fade-in duration-500">
          <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-4">
              <div className="w-11 h-11 rounded-xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center shadow-inner border border-slate-200 dark:border-slate-700">
                {jobStatus?.status === "processing" ? <Loader2 size={20} className="text-primary-600 dark:text-primary-400 animate-spin" /> : jobStatus?.status === "completed" ? <CheckCircle2 size={20} className="text-emerald-500" /> : jobStatus?.status === "failed" ? <AlertCircle size={20} className="text-rose-500" /> : <Loader2 size={20} className="text-slate-500 dark:text-slate-400 animate-spin" />}
              </div>
              <div>
                <h3 className="font-bold text-slate-800 dark:text-slate-200 uppercase tracking-tight text-base leading-none mb-1">
                  {jobStatus?.status === "processing" ? t("attendance_import.status.processing") : jobStatus?.status === "completed" ? t("attendance_import.status.completed") : jobStatus?.status === "failed" ? t("attendance_import.status.failed") : t("attendance_import.status.pending")}
                </h3>
                <p className="text-[10px] font-bold text-slate-600 dark:text-slate-400 uppercase tracking-[0.2em]">{jobStatus?.processed_rows || 0} / {jobStatus?.total_rows || 0} {t("attendance_import.rows_processed")}</p>
              </div>
            </div>
            {jobStatus?.total_rows ? <span className="text-[10px] font-bold text-primary-700 dark:text-primary-400 bg-primary-50 dark:bg-primary-950 px-3 py-1 rounded-full border border-primary-200 dark:border-primary-800 shadow-sm">{Math.round((jobStatus.processed_rows / jobStatus.total_rows) * 100)}%</span> : null}
          </div>

          <div className="h-2.5 w-full bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden shadow-inner border border-slate-200 dark:border-slate-700/50 relative">
            <div className={cn("h-full transition-all duration-1000 shadow-xl", jobStatus?.status === "failed" ? "bg-rose-400 dark:bg-rose-500" : "bg-primary-600")} style={{ width: `${jobStatus?.total_rows ? (jobStatus.processed_rows / jobStatus.total_rows) * 100 : 0}%` }}>
               <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-shimmer" style={{ backgroundSize: '200% 100%' }} />
            </div>
          </div>

          {jobStatus?.error_log && (
            <div className="bg-slate-50 dark:bg-slate-900 rounded-2xl p-6 border border-rose-200 dark:border-rose-900/50 shadow-sm relative overflow-hidden">
              <h4 className="text-[10px] font-bold text-rose-600 dark:text-rose-400 mb-4 flex items-center gap-2 uppercase tracking-[0.25em]"><AlertCircle size={14} /> {t("attendance_import.error_list_title")}</h4>
              <div className="space-y-2 max-h-48 overflow-y-auto pr-2 custom-scrollbar relative z-10">
                {jobStatus.error_log.split("\n").map((err: string, i: number) => (<div key={i} className="text-[11px] bg-white dark:bg-slate-800 p-3 rounded-lg border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 font-mono leading-relaxed"><span className="text-rose-500 mr-2 font-bold uppercase">ERR:</span> {err}</div>))}
              </div>
            </div>
          )}

          {isFinished && (
            <div className="pt-3 flex justify-end border-t border-slate-200 dark:border-slate-800">
              <button onClick={() => { setActiveJobId(null); queryClient.invalidateQueries(); }} className="px-10 py-3 bg-slate-800 dark:bg-slate-700 text-white rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-primary-700 transition-all shadow-lg active:scale-95">{t("common.close").toUpperCase()}</button>
            </div>
          )}
        </div>
      ) : (
        <div className="space-y-6 pt-2 animate-in fade-in duration-500">
          <div className="bg-primary-50 dark:bg-primary-950/50 rounded-2xl p-5 border border-primary-200 dark:border-primary-800/50 flex gap-4">
            <div className="w-9 h-9 rounded-xl bg-white dark:bg-slate-900 flex items-center justify-center text-primary-600 dark:text-primary-400 shadow-sm border border-primary-200 dark:border-primary-800 shrink-0"><AlertCircle size={18} /></div>
            <div className="text-xs text-primary-800 dark:text-primary-200 leading-relaxed font-medium pt-0.5">
              <p className="font-bold uppercase tracking-[0.2em] mb-2 text-slate-700 dark:text-slate-300">{t("attendance_import.file_requirements.title")}</p>
              <ul className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-1.5 text-slate-600 dark:text-slate-400 font-bold uppercase tracking-tight">
                {customRequirements ? (
                  customRequirements.map((req, i) => (
                    <li key={i} className="flex items-center gap-2"><div className="w-1.5 h-1.5 bg-primary-500 dark:bg-primary-400 rounded-full" /> {req}</li>
                  ))
                ) : (
                  <>
                    <li className="flex items-center gap-2"><div className="w-1.5 h-1.5 bg-primary-500 dark:bg-primary-400 rounded-full" /> {t("attendance_import.file_requirements.col_a")}</li>
                    <li className="flex items-center gap-2"><div className="w-1.5 h-1.5 bg-primary-500 dark:bg-primary-400 rounded-full" /> {t("attendance_import.file_requirements.col_b")}</li>
                    <li className="flex items-center gap-2"><div className="w-1.5 h-1.5 bg-primary-500 dark:bg-primary-400 rounded-full" /> {t("attendance_import.file_requirements.col_c")}</li>
                    <li className="flex items-center gap-2"><div className="w-1.5 h-1.5 bg-primary-500 dark:bg-primary-400 rounded-full" /> {t("attendance_import.file_requirements.formats")}</li>
                  </>
                )}
              </ul>
            </div>
          </div>

          { }
          <label htmlFor="file-upload" className={cn("border-3 border-dashed rounded-2xl p-10 flex flex-col items-center justify-center transition-all cursor-pointer group active:scale-[0.98] relative overflow-hidden w-full", file ? "border-emerald-400 bg-emerald-50 dark:bg-emerald-950/20" : "border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/30 hover:border-primary-400 hover:bg-primary-50 dark:hover:bg-primary-950/30")}>
            <input id="file-upload" aria-label="File Upload" type="file" className="hidden" accept=".xlsx,.xls,.csv" onChange={(e) => setFile(e.target.files?.[0] || null)} />
            {file ? (
              <div className="text-center animate-in zoom-in-95 duration-500">
                <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900 rounded-2xl flex items-center justify-center mx-auto mb-5 shadow-lg shadow-emerald-200/50 dark:shadow-emerald-900/30 rotate-3 group-hover:rotate-0 transition-transform"><FileText size={28} className="text-emerald-600 dark:text-emerald-300" /></div>
                <p className="font-bold text-slate-800 dark:text-slate-200 mb-1 text-lg tracking-tight uppercase">{file.name}</p>
                <p className="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">{(file.size / 1024).toFixed(1)} KB — READY TO START</p>
                <button onClick={(e) => { e.stopPropagation(); setFile(null); }} className="mt-5 text-[10px] font-bold text-rose-600 dark:text-rose-400 uppercase tracking-widest hover:text-rose-700 dark:hover:text-rose-300 transition-all bg-white dark:bg-slate-900 px-5 py-2 rounded-lg border border-rose-200 dark:border-rose-800 shadow-sm hover:shadow-md active:scale-90">{t("attendance_import.select_another_file")}</button>
              </div>
            ) : (
              <div className="text-center group-hover:scale-105 transition-transform duration-500">
                <div className="w-16 h-16 bg-white dark:bg-slate-900 rounded-2xl flex items-center justify-center mx-auto mb-5 shadow-lg border border-slate-200 dark:border-slate-700 -rotate-3 group-hover:rotate-0 transition-all"><Upload size={28} className="text-slate-400 dark:text-slate-500" /></div>
                <p className="font-bold text-slate-800 dark:text-slate-200 mb-1 text-lg tracking-tight uppercase">{t("attendance_import.upload_prompt")}</p>
                <p className="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">{t("attendance_import.upload_limit")}</p>
              </div>
            )}
          </label>

          <div className="flex gap-4 pt-3 border-t border-slate-200 dark:border-slate-800">
            <button onClick={onClose} className="flex-1 px-6 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 rounded-xl font-bold text-[10px] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-800 transition-all active:scale-95">{t("common.cancel")}</button>
            <button disabled={!file || uploading} onClick={handleUpload} className="flex-[1.5] py-3 bg-primary-600 text-white rounded-xl font-bold text-[10px] uppercase tracking-widest hover:bg-primary-700 transition-all shadow-lg shadow-primary-200/50 dark:shadow-primary-900/30 active:scale-95 disabled:opacity-50 flex items-center justify-center gap-3">
              {uploading ? <><Loader2 size={18} className="animate-spin" /> {t("attendance_import.status.uploading").toUpperCase()}</> : t("attendance_import.start_import").toUpperCase()}
            </button>
          </div>
        </div>
      )}
    </Modal>
  );
}

import { useState, useMemo } from "react";

import { useTranslation } from "react-i18next";
import {
    BarChart,
    Bar,
    XAxis,
    YAxis,
    CartesianGrid,
    PieChart,
    Pie,
    Cell,
    ResponsiveContainer,
    Tooltip,
    Legend,
} from "recharts";

import { useTurnoverAnalytics } from "@/hooks/use-dashboard";

type TabKey = "tenure" | "source" | "department";

interface PeriodOption {
    label: string;
    value: string;
    startDate: string;
    endDate: string;
}

function formatDate(d: Date): string {
    return d.toISOString().slice(0, 10);
}

function getPeriodOptions(t: (key: string) => string): PeriodOption[] {
    const today = new Date();
    const endDate = formatDate(today);

    const months3 = new Date(today);
    months3.setMonth(months3.getMonth() - 3);

    const months6 = new Date(today);
    months6.setMonth(months6.getMonth() - 6);

    const year1 = new Date(today);
    year1.setFullYear(year1.getFullYear() - 1);

    const year2 = new Date(today);
    year2.setFullYear(year2.getFullYear() - 2);

    return [
        { label: t("dashboard.hr.turnover_period_3m"), value: "3m", startDate: formatDate(months3), endDate },
        { label: t("dashboard.hr.turnover_period_6m"), value: "6m", startDate: formatDate(months6), endDate },
        { label: t("dashboard.hr.turnover_period_1y"), value: "1y", startDate: formatDate(year1), endDate },
        { label: t("dashboard.hr.turnover_period_2y"), value: "2y", startDate: formatDate(year2), endDate },
    ];
}

const SOURCE_COLORS = [
    "#22c55e", "#3b82f6", "#f59e0b", "#06b6d4", "#10b981",
    "#ec4899", "#14b8a6", "#f97316",
];

const TENURE_COLOR = "#6366f1";
const DEPT_COLOR = "#3b82f6";

export default function TurnoverAnalyticsChart() {
    const { t } = useTranslation();
    const [activeTab, setActiveTab] = useState<TabKey>("tenure");
    const [selectedPeriod, setSelectedPeriod] = useState("6m");

    const periods = useMemo(() => getPeriodOptions(t), [t]);
    const currentPeriod = periods.find((p) => p.value === selectedPeriod) ?? periods[1];

    const { data, isLoading } = useTurnoverAnalytics(
        currentPeriod.startDate,
        currentPeriod.endDate
    );

    const tabs: { key: TabKey; labelKey: string }[] = [
        { key: "tenure", labelKey: "dashboard.hr.turnover_tenure" },
        { key: "source", labelKey: "dashboard.hr.turnover_by_source" },
        { key: "department", labelKey: "dashboard.hr.turnover_by_dept" },
    ];

    if (isLoading) {
        return (
            <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-10 border border-slate-100 dark:border-slate-800 shadow-sm animate-pulse">
                <div className="h-4 w-48 bg-slate-200 dark:bg-slate-700 rounded-full mb-8" />
                <div className="h-64 bg-slate-100 dark:bg-slate-800 rounded-3xl" />
            </div>
        );
    }

    const isEmpty =
        !data ||
        (data.tenure_distribution.length === 0 &&
            data.by_source.length === 0 &&
            data.by_department.length === 0);

    return (
        <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-10 border border-slate-100 dark:border-slate-800 shadow-sm">
            {/* Header with period selector */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
                <div>
                    <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-200">
                        {t("dashboard.hr.turnover_title")}
                    </h3>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
                        {t("dashboard.hr.turnover_subtitle")}
                    </p>
                </div>

                <div className="flex items-center gap-3">
                    {/* Total badge */}
                    {data && (
                        <span className="text-xs font-bold text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-950 px-4 py-1.5 rounded-full uppercase tracking-widest border border-rose-100 dark:border-rose-800 shadow-sm">
                            {t("dashboard.hr.turnover_total")}: {data.total_terminated}
                        </span>
                    )}

                    {/* Period selector */}
                    <select aria-label="Turnover Period"
                        value={selectedPeriod}
                        onChange={(e) => setSelectedPeriod(e.target.value)}
                        className="text-xs font-bold text-slate-600 dark:text-slate-300 bg-slate-50 dark:bg-slate-800 px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-primary-500 uppercase tracking-widest cursor-pointer"
                    >
                        {periods.map((p) => (
                            <option key={p.value} value={p.value}>
                                {p.label}
                            </option>
                        ))}
                    </select>
                </div>
            </div>

            {/* Tab navigation */}
            <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-2xl w-fit mb-6 border border-slate-200/50 dark:border-slate-700/50">
                {tabs.map((tab) => (
                    <button
                        key={tab.key}
                        onClick={() => setActiveTab(tab.key)}
                        className={`px-5 py-2 rounded-xl text-xs font-bold uppercase tracking-widest transition-all ${activeTab === tab.key
                                ? "bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-400 shadow-sm border border-slate-100 dark:border-slate-800"
                                : "text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200"
                            }`}
                    >
                        {t(tab.labelKey)}
                    </button>
                ))}
            </div>

            {/* Chart content */}
            {isEmpty ? (
                <div className="flex items-center justify-center h-64 text-slate-400">
                    {t("common.no_data")}
                </div>
            ) : (
                <div style={{ height: 320 }}>
                    {activeTab === "tenure" && <TenureChart data={data!.tenure_distribution} />}
                    {activeTab === "source" && <SourceChart data={data!.by_source} t={t} />}
                    {activeTab === "department" && <DepartmentChart data={data!.by_department} />}
                </div>
            )}
        </div>
    );
}

// ── Sub-charts ──────────────────────────────────────────────────────

function TenureChart({ data }: { data: { bucket: string; count: number }[] }) {
    return (
        <ResponsiveContainer width="100%" height="100%">
            <BarChart data={data} margin={{ top: 10, right: 20, left: 0, bottom: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                    dataKey="bucket"
                    tick={{ fontSize: 11, fill: "#94a3b8" }}
                    axisLine={false}
                    tickLine={false}
                />
                <YAxis
                    allowDecimals={false}
                    tick={{ fontSize: 11, fill: "#94a3b8" }}
                    axisLine={false}
                    tickLine={false}
                />
                <Tooltip
                    contentStyle={{
                        borderRadius: "12px",
                        border: "none",
                        boxShadow: "0 4px 20px rgba(0,0,0,0.1)",
                        fontSize: 12,
                    }}
                />
                <Bar dataKey="count" fill={TENURE_COLOR} radius={[8, 8, 0, 0]} />
            </BarChart>
        </ResponsiveContainer>
    );
}

function SourceChart({
    data,
    t,
}: {
    data: { source_type: string; source_name: string; count: number }[];
    t: (key: string) => string;
}) {
    const chartData = data
        .filter((d) => d.count > 0)
        .map((d, i) => ({
            name: d.source_name,
            value: d.count,
            fill: SOURCE_COLORS[i % SOURCE_COLORS.length],
        }));

    const total = chartData.reduce((acc, d) => acc + d.value, 0);

    return (
        <div className="flex flex-col lg:flex-row items-center gap-4 h-full">
            <div className="w-full lg:w-1/2 h-full">
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie
                            data={chartData}
                            cx="50%"
                            cy="50%"
                            innerRadius={55}
                            outerRadius={95}
                            paddingAngle={3}
                            dataKey="value"
                            nameKey="name"
                            stroke="none"
                        >
                            {chartData.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={entry.fill} />
                            ))}
                        </Pie>
                        <Tooltip
                            contentStyle={{
                                borderRadius: "12px",
                                border: "none",
                                boxShadow: "0 4px 20px rgba(0,0,0,0.1)",
                            }}
                            formatter={(value: any) => [
                                `${value ?? 0} (${(((value ?? 0) / total) * 100).toFixed(1)}%)`,
                                t("dashboard.hr.people"),
                            ]}
                        />
                        <Legend verticalAlign="bottom" iconType="circle" iconSize={8} />
                    </PieChart>
                </ResponsiveContainer>
            </div>
            <div className="w-full lg:w-1/2 space-y-2">
                {chartData.map((entry, index) => (
                    <div
                        key={index}
                        className="flex items-center justify-between px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800/50"
                    >
                        <div className="flex items-center gap-2">
                            <span
                                className="w-3 h-3 rounded-full inline-block"
                                style={{ backgroundColor: entry.fill }}
                            />
                            <span className="text-sm text-slate-700 dark:text-slate-300">
                                {entry.name}
                            </span>
                        </div>
                        <span className="text-sm font-medium text-slate-900 dark:text-slate-100">
                            {entry.value}
                        </span>
                    </div>
                ))}
            </div>
        </div>
    );
}

function DepartmentChart({ data }: { data: { department_name: string; count: number }[] }) {
    return (
        <ResponsiveContainer width="100%" height="100%">
            <BarChart
                data={data}
                layout="vertical"
                margin={{ top: 10, right: 20, left: 10, bottom: 10 }}
            >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis
                    type="number"
                    allowDecimals={false}
                    tick={{ fontSize: 11, fill: "#94a3b8" }}
                    axisLine={false}
                    tickLine={false}
                />
                <YAxis
                    dataKey="department_name"
                    type="category"
                    tick={{ fontSize: 11, fill: "#94a3b8" }}
                    axisLine={false}
                    tickLine={false}
                    width={120}
                />
                <Tooltip
                    contentStyle={{
                        borderRadius: "12px",
                        border: "none",
                        boxShadow: "0 4px 20px rgba(0,0,0,0.1)",
                        fontSize: 12,
                    }}
                />
                <Bar dataKey="count" fill={DEPT_COLOR} radius={[0, 8, 8, 0]} />
            </BarChart>
        </ResponsiveContainer>
    );
}

